-- Phase Q: exact net worth by currency. Archived sources with live balances
-- remain included; lifecycle visibility must not erase assets/liabilities.
create function public.get_net_worth()returns table(currency text,wallet_assets numeric,receivables numeric,liabilities numeric,net_worth numeric)
language sql security invoker stable set search_path='' as $$
with wallet_values as(select w.currency,coalesce(sum(e.amount) filter (where t.deleted_at is null),0) as amount from public.wallets as w left join public.transaction_entries as e on e.wallet_id=w.id left join public.transactions as t on t.id=e.transaction_id group by w.id,w.currency),wallet_total as(select currency,sum(amount) as amount from wallet_values group by currency),debt_values as(select d.currency,d.debt_type,coalesce(sum(case when ev.event_kind in('DRAW','DISBURSEMENT')then ev.principal_amount else -ev.principal_amount end) filter (where t.deleted_at is null),0) as amount from public.debt_accounts as d left join public.debt_events as ev on ev.debt_account_id=d.id left join public.transactions as t on t.id=ev.principal_transaction_id group by d.id,d.currency,d.debt_type),debt_total as(select currency,coalesce(sum(amount) filter (where debt_type='RECEIVABLE'),0) as receivables,coalesce(sum(amount) filter (where debt_type='LIABILITY'),0) as liabilities from debt_values group by currency),currencies as(select currency from wallet_total union select currency from debt_total)
select c.currency,coalesce(w.amount,0),coalesce(d.receivables,0),coalesce(d.liabilities,0),coalesce(w.amount,0)+coalesce(d.receivables,0)-coalesce(d.liabilities,0)from currencies as c left join wallet_total as w using(currency)left join debt_total as d using(currency)order by c.currency
$$;
revoke execute on function public.get_net_worth()from public,anon;grant execute on function public.get_net_worth()to authenticated;
